UPDATE competitor_products
SET m01_active = 0
WHERE marketplace = #{marketplace}
  AND m01_active = 1
  AND (
      available_date IS NULL OR available_date <= 0
      OR DATEDIFF(NOW(), FROM_UNIXTIME(available_date / 1000)) >= #{listingDaysMax}
  )

UPDATE competitor_products_clean
SET m01_active = 0
WHERE marketplace = #{marketplace}
  AND m01_active = 1
  AND (
      available_date IS NULL OR available_date <= 0
      OR DATEDIFF(NOW(), FROM_UNIXTIME(available_date / 1000)) >= #{listingDaysMax}
  )
